package gateway
import("encoding/json";"net/http";"strings";"github.com/jiejhong/GooseCab/internal/transfer")
type TransferAPI struct{Service *transfer.Service}
func(a *TransferAPI)Handler(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){p:=strings.TrimSuffix(r.URL.Path,"/");if !strings.HasPrefix(p,"/api/transfers"){next.ServeHTTP(w,r);return};if p=="/api/transfers"&&r.Method==http.MethodPost{var m transfer.Metadata;if !decode(w,r,&m){return};x,e:=a.Service.Save(r.Context(),m,"transfer.request");if e!=nil{http.Error(w,e.Error(),500);return};w.WriteHeader(201);out(w,x);return};parts:=strings.Split(strings.TrimPrefix(p,"/api/transfers/"),"/");if len(parts)==2&&r.Method==http.MethodPost{var body struct{Status string `json:"status"`;Offset int64 `json:"offset"`};if json.NewDecoder(r.Body).Decode(&body)!=nil{http.Error(w,"invalid json",400);return};m,ok:=a.Service.Get(parts[0]);if !ok{http.NotFound(w,r);return};m.Status=body.Status;m.Offset=body.Offset;typ:="transfer."+body.Status;x,e:=a.Service.Save(r.Context(),m,typ);if e!=nil{http.Error(w,e.Error(),500);return};out(w,x);return};http.NotFound(w,r)})}
